import gurobipy as gp
from gurobipy import GRB
skill_level = {'Junior': 1, 'Intermediate': 2, 'Senior': 3, 'Expert': 4}
workers = []
worker_skill = {}
worker_on_leave = {}
projects = []
project_required_skill = {}
cost_matrix = {}
for rec in LEGACY_RECORDS:
    v = rec['values']
    if 'worker_id' in v and 'skill' in v:
        wid = v['worker_id']
        workers.append(wid)
        worker_skill[wid] = v['skill']
        worker_on_leave[wid] = int(v['on_leave'])
    if 'project_id' in v and 'required_skill' in v:
        pid = v['project_id']
        projects.append(pid)
        project_required_skill[pid] = v['required_skill']
eligible_workers = [w for w in workers if worker_on_leave[w] == 0]
for rec in LEGACY_RECORDS:
    v = rec['values']
    if 'worker_id' in v and any((k.startswith('P') for k in v)):
        wid = v['worker_id']
        if wid not in eligible_workers:
            continue
        if wid not in cost_matrix:
            cost_matrix[wid] = {}
        for pid in projects:
            sval = v.get(pid, '')
            if sval != '':
                cost_matrix[wid][pid] = int(sval)
eligibility = {}
for w in eligible_workers:
    eligibility[w] = {}
    w_skill = skill_level[worker_skill[w]]
    for p in projects:
        p_skill = skill_level[project_required_skill[p]]
        eligible = 0
        if w in cost_matrix and p in cost_matrix[w]:
            if w_skill >= p_skill:
                eligible = 1
        eligibility[w][p] = eligible
for p in projects:
    if not any((eligibility[w][p] for w in eligible_workers)):
        raise ValueError(f'No eligible worker for project {p}')
for w in eligible_workers:
    for p in projects:
        if eligibility[w][p]:
            if w not in cost_matrix or p not in cost_matrix[w]:
                raise ValueError(f'Missing cost for eligible pair ({w},{p})')
m = gp.Model('AP_Legacy')
x_vars = m.addVars(eligible_workers, projects, vtype=GRB.BINARY, name='')
m.setObjective(gp.quicksum((cost_matrix[w][p] * x_vars[w, p] for w in eligible_workers for p in projects if eligibility[w][p])), GRB.MINIMIZE)
for p in projects:
    m.addConstr(gp.quicksum((x_vars[w, p] for w in eligible_workers if eligibility[w][p])) == 1)
for w in eligible_workers:
    m.addConstr(gp.quicksum((x_vars[w, p] for p in projects if eligibility[w][p])) <= 1)
for w in eligible_workers:
    for p in projects:
        if not eligibility[w][p]:
            m.addConstr(x_vars[w, p] == 0)
m.Params.MIPGap = 0.0001
m.optimize()
if m.Status == GRB.OPTIMAL:
    print(f'ObjVal: {m.ObjVal}')
    for v in m.getVars():
        print(f'{v.VarName}: {v.X}')
else:
    print(f'Solver status: {m.Status}')